    # 'Y' if (i*j)%7 in {0,1,6}
    M = []
    for i in range(1, n+1):
        row = bytearray(n)
        for j in range(1, n+1):
            r = (i*j) % 7
            if r == 0 or r == 1 or r == 6:
                row[j-1] = 1
        M.append(row)

    ans0 = 0
    ans90 = 0
    ans180 = 0
    ans270 = 0

    # 180 rotation
    for i in range(n):
        row_i = M[i]
        row_180 = M[n-1-i]
        for j in range(n):
            if row_i[j] != row_180[n-1-j]:
                ans180 += 1

    # 90 rotation
    for i in range(n):
        row_i = M[i]
        for j in range(n):
            if row_i[j] != M[j][n-1-i]:
                ans90 += 1

    # 270 rotation
    for i in range(n):
        row_i = M[i]
        for j in range(n):
            if row_i[j] != M[n-1-j][i]:
                ans270 += 1

    ans_map = {0: ans0, 90: ans90, 180: ans180, 270: ans270}

    out_lines = []
    for angle in queries:
        a = angle % 360
        out_lines.append(str(ans_map[a]))

    sys.stdout.write("\n".join(out_lines))

if __name__ == "__main__":
    solve()

