import sys
from bisect import bisect_right

def solve():
    input_data = sys.stdin.read().strip().split()
    it = iter(input_data)
    T = int(next(it))
    out = []
    for _ in range(T):
        N = int(next(it))
        dishes = []
        for _ in range(N):
            M = int(next(it))
            A = [int(next(it)) for _ in range(M)]
            dishes.append(A)

        if N == 1:
            out.append("0")
            continue

        # Build pairs for each dish
        dish_pairs = []
        for A in dishes:
            M = len(A)
            if M == 1:
                pairs = [(A[0], A[0])]
            else:
                pairs = []
                for j in range(M):
                    l = A[j]
                    f = A[(j+1) % M]
                    pairs.append((f, l))
            dish_pairs.append(pairs)

        # Initialize dp for dish 0
        dp = {}
        for f, l in dish_pairs[0]:
            dp[l] = 0  # max over same l is 0

        for i in range(1, N):
            w = i  # because term index is i (1-based) between dish i and i+1
            # prev_vals from dp keys
            prev_vals = sorted(dp.keys())
            prev_dp_list = [dp[v] for v in prev_vals]
            n_prev = len(prev_vals)

            # Precompute left_max and right_max
            left_max = [0]*n_prev
            right_max = [0]*n_prev

            # left_max[k] = max_{j<=k} (dp[prev_vals[j]] - w*prev_vals[j])
            cur = -10**18
            for k in range(n_prev):
                val = prev_dp_list[k] - w * prev_vals[k]
                if val > cur:
                    cur = val
                left_max[k] = cur

            # right_max[k] = max_{j>=k} (dp[prev_vals[j]] + w*prev_vals[j])
            cur = -10**18
            for k in range(n_prev-1, -1, -1):
                val = prev_dp_list[k] + w * prev_vals[k]
                if val > cur:
                    cur = val
                right_max[k] = cur

            new_dp = {}
            for f, l in dish_pairs[i]:
                idx = bisect_right(prev_vals, f) - 1
                best = -10**18
                if idx >= 0:
                    cand = left_max[idx] + w * f
                    if cand > best:
                        best = cand
                if idx + 1 < n_prev:
                    cand = right_max[idx+1] - w * f
                    if cand > best:
                        best = cand
                if l in new_dp:
                    if best > new_dp[l]:
                        new_dp[l] = best
                else:
                    new_dp[l] = best
            dp = new_dp

        ans = max(dp.values())
        out.append(str(ans))

    sys.stdout.write("\n".join(out))

if __name__ == "__main__":
    solve()

