import sys

def inversion_count(arr):
    # arr: list of integers (1-based positions)
    n = len(arr)
    bit = [0] * (n + 2)
    def update(i, v):
        while i <= n:
            bit[i] += v
            i += i & -i
    def query(i):
        s = 0
        while i > 0:
            s += bit[i]
            i -= i & -i
        return s
    inv = 0
    for i in range(n - 1, -1, -1):
        inv += query(arr[i] - 1)
        update(arr[i], 1)
    return inv

